{"implementation": "def solve(case):
    nodes = case["nodes"]
    required_symbols = set(case["required_symbols"])
    removed = set()
    # Process nodes in input order; parents are guaranteed to appear before children
    for node in nodes:
        nid = node["id"]
        parent_id = node["parent"]
        # Cascade removal: if parent was removed, remove this node too
        if parent_id is not None and parent_id in removed:
            removed.add(nid)
        # Direct removal: node is removable and its symbol is not required
        elif node["removable"] and node["symbol"] not in required_symbols:
            removed.add(nid)
    all_ids = [n["id"] for n in nodes]
    return {
        "removed_node_ids": [nid for nid in all_ids if nid in removed],
        "retained_node_ids": [nid for nid in all_ids if nid not in removed]
    }
"}
